// Custom Worker entry: OpenNext's generated worker plus a `scheduled` handler for the Cron Trigger.
// wrangler.jsonc points `main` here; this file is bundled by wrangler, not by Next.
// The file exists only after a Cloudflare build, so @ts-expect-error would fail once it does.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore: generated by `opennextjs-cloudflare build`
import openNextWorker from "./.open-next/worker.js";
import { logged } from "./src/lib/request-log";

// Re-exported so Durable Object bindings added later (queue, tag cache) keep working.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore: generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";

type WorkerEnv = Record<string, unknown> & { CRON_SECRET?: string; INBOUND_WORKER_SECRET?: string };

const worker = {
  // One content-free log line per request (src/lib/request-log.ts): the ray, route, household id, status and duration.
  fetch: (request: Request, env: WorkerEnv, ctx: { waitUntil(p: Promise<unknown>): void }) => logged(request, () => openNextWorker.fetch(request, env, ctx)),

  async email(message: { to: string; rawSize: number; raw: ReadableStream; setReject(reason: string): void }, env: WorkerEnv, ctx: { waitUntil(p: Promise<unknown>): void }) {
    if (!env.INBOUND_WORKER_SECRET) throw new Error("INBOUND_WORKER_SECRET is not set");
    if (message.rawSize > 6 * 1024 * 1024) { message.setReject("Message exceeds the 6 MiB limit."); return; }
    const request = new Request("https://worker.internal/api/inbound", {
      method: "POST", headers: { "content-type": "message/rfc822", origin: "https://worker.internal",
        authorization: "Bearer " + env.INBOUND_WORKER_SECRET, "x-envelope-to": message.to },
      body: await new Response(message.raw).arrayBuffer(),
    });
    const response = await openNextWorker.fetch(request, env, ctx);
    if (response.status === 404) { message.setReject("Unknown delivery address."); return; }
    if (!response.ok) throw new Error("Inbound email could not be accepted");
  },

  // Daily trigger: call the app's own /api/cron route through the same Next handler.
  async scheduled(controller: { cron: string }, env: WorkerEnv, ctx: { waitUntil(p: Promise<unknown>): void }) {
    const request = new Request("https://worker.internal/api/cron", {
      headers: { authorization: `Bearer ${env.CRON_SECRET ?? ""}` },
    });
    ctx.waitUntil(
      (async () => {
        const response = await openNextWorker.fetch(request, env, ctx);
        console.log(`[cron] ${controller.cron} -> ${response.status}`);
      })(),
    );
  },
};

export default worker;
